package com.latchpoint.auth.config;
import com.latchpoint.auth.model.User; import com.latchpoint.auth.repository.UserRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class SeedConfiguration { @Bean CommandLineRunner seed(UserRepository repo,PasswordEncoder encoder,AppProperties p){return args->{if(!p.getSeed().isEnabled()||p.getSeed().getPassword()==null||p.getSeed().getPassword().isBlank()||repo.findByUsername(p.getSeed().getUsername()).isPresent())return;User u=new User();u.setUsername(p.getSeed().getUsername());u.setPasswordHash(encoder.encode(p.getSeed().getPassword()));u.setMfaEnabled(false);u.setEnabled(true);repo.save(u);};}}
